// Ensure we are handling the data correctly from the XML node
const entries = $node["XML"].json.feed.entry;

// Handle cases with 0, 1, or many papers
if (!entries) return []; 
const entriesArray = Array.isArray(entries) ? entries : [entries];

return entriesArray
  .map(paper => {
    const id = paper.id?._text || paper.id || "";

    return {
      title: paper.title?._text || paper.title || 'No Title',
      abstract: paper.summary?._text || paper.summary || 'No Abstract',
      url: id,
      authors: Array.isArray(paper.author) 
        ? paper.author.map(a => a.name?._text || a.name).join(', ') 
        : (paper.author?.name?._text || paper.author?.name || 'Unknown Author'),
      published: paper.published?._text || paper.published,
      // Helper to identify the version
      isFirstVersion: id.includes('v1')
    };
  })
  // FILTER: Only keep the paper if it is a v1 (new submission)
  .filter(paper => paper.isFirstVersion);

// 1. Safely grab the arrays
const titles = $node["HTML"].json.titles || [];
const scites = $node["HTML"].json.scites || [];
const uids = $node["HTML"].json.uid || [];
const abstracts = $node["HTML"].json.abstracts || [];
const authors = $node["HTML"].json.authors || [];

// 2. Defensive check
if (titles.length === 0) return [];

// 3. Zip, Clean, and Extract
return titles.map((title, index) => {
  const rawUid = uids[index] || "";

  // --- DATE EXTRACTION ---
  // Matches "May 12 2026" at the start of the string
  const dateMatch = rawUid.match(/^[A-Z][a-z]{2}\s\d{2}\s\d{4}/);
  const cleanDate = dateMatch ? dateMatch[0] : "Unknown Date";

  // --- AUTHOR CLEANING ---
  let rawAuthors = authors[index] || "Unknown Authors";
  let cleanAuthors = rawAuthors
    .replace(/\[\/search\?q=[^\]]+\]/g, '') // Strip links
    .replace(/\n/g, ' ')                   // Strip newlines
    .replace(/\s+/g, ' ')                  // Consolidate spaces
    .replace(/,\s*,/g, ',')                // Fix double commas
    .trim()
    .replace(/,$/, '');                    // Remove trailing comma

  // --- SCITE & ID EXTRACTION ---
  const rawScite = scites[index] || "0";
  const sciteCount = parseInt(rawScite.replace(/[^0-9]/g, ''), 10) || 0;

  const idMatch = rawUid.match(/[0-9]{4}\.[0-9]{4,5}(v[0-9]+)?/);
  const cleanId = idMatch ? idMatch[0] : "unknown";

  return {
    json: {
      title: title.trim(),
      authors: cleanAuthors,
      published: cleanDate,
      abstract: abstracts[index] ? abstracts[index].trim() : "No abstract available.",
      scites: sciteCount,
      arxivId: cleanId,
      url: `https://arxiv.org/abs/${cleanId.split('v')[0]}`
    }
  };
}).filter(item => item.json.scites >= Number($env.SCIRATE_MIN_SCITES || 10));

