const fs = require('fs');
const path = require('path');

const overflowPath = path.join('/data', 'arxiv_overflow.json');
const libraryPath = path.join('/data', 'citation_lookup_library.json');

const TARGET_ZOTERO_COLLECTION = $env.ZOTERO_COLLECTION_KEY;

// 1. Extract LLM Output
const rawInput = $input.all()[0]?.json || {};
const input = rawInput.output || rawInput;

let primary = Array.isArray(input.primary) ? [...input.primary] : [];
let overflowIncoming = Array.isArray(input.overflow) ? input.overflow : [];

const formatAuthors = (auth) => Array.isArray(auth) ? auth.join(', ') : (auth || '');
const primaryIds = new Set(primary.map(p => p.arxivId).filter(Boolean));

// 2. Load & Sync Overflow Buffer
let overflowBuffer = [];
if (fs.existsSync(overflowPath)) {
    try { 
        overflowBuffer = JSON.parse(fs.readFileSync(overflowPath, 'utf8') || '[]'); 
    } catch (e) { 
        overflowBuffer = []; 
    }
}

const overflowIds = new Set(overflowBuffer.map(p => p.arxivId).filter(Boolean));

overflowIncoming.forEach(paper => {
    if (paper.arxivId && !overflowIds.has(paper.arxivId) && !primaryIds.has(paper.arxivId)) {
        overflowBuffer.push(paper);
        overflowIds.add(paper.arxivId);
    }
});

// 3. Backfill Primary if LLM selected < 3
let idx = 0;
while (primary.length < 3 && idx < overflowBuffer.length) {
    const candidate = overflowBuffer[idx];

    if (!primaryIds.has(candidate.arxivId)) {
        primary.push(candidate);
        primaryIds.add(candidate.arxivId);
        overflowBuffer.splice(idx, 1);
    } else {
        overflowBuffer.splice(idx, 1);
    }
}

// 4. Fallback: Citation Snowball Library
let library = {};
let libraryModified = false;

if (primary.length < 3 && fs.existsSync(libraryPath)) {
    try { 
        library = JSON.parse(fs.readFileSync(libraryPath, 'utf8') || '{}'); 
    } catch (e) { 
        library = {}; 
    }

    let entries = Object.entries(library);

    while (primary.length < 3 && entries.length > 0) {
        const totalWeight = entries.reduce((sum, entry) => sum + (entry[1].hit_count || 1), 0);
        let target = Math.random() * totalWeight;
        let chosenIndex = 0;

        for (let i = 0; i < entries.length; i++) {
            target -= (entries[i][1].hit_count || 1);
            if (target <= 0) { chosenIndex = i; break; }
        }

        const [key, chosenPaper] = entries[chosenIndex];
        const paperArxivId = chosenPaper.arxiv || chosenPaper.arxivId || chosenPaper.doi || key;

        if (!primaryIds.has(paperArxivId)) {
            primary.push({
                title: chosenPaper.title || "Untitled Citation",
                arxivId: paperArxivId,
                url: chosenPaper.arxiv ? `https://arxiv.org/abs/${chosenPaper.arxiv}` : (chosenPaper.url || "#"),
                authors: chosenPaper.authors || ""
            });
            primaryIds.add(paperArxivId);
        }

        delete library[key];
        entries.splice(chosenIndex, 1);
        libraryModified = true;
    }
}

// 5. Save Overflow & Library States
try {
    fs.writeFileSync(overflowPath, JSON.stringify(overflowBuffer, null, 2), 'utf8');
    if (libraryModified) {
        fs.writeFileSync(libraryPath, JSON.stringify(library, null, 2), 'utf8');
    }
} catch (err) { 
    console.error("Write error:", err); 
}

// 6. Output formatted items with current overflow count
const finalOverflowCount = overflowBuffer.length;

return primary.slice(0, 3).map(paper => ({
    json: { 
        arxivId: paper.arxivId,
        arxiv_id: paper.arxivId, 
        doi: paper.doi || paper.meta?.doi || null,
        debugTitle: paper.title,
        url: paper.url || `https://arxiv.org/abs/${paper.arxivId}`,
        authors: formatAuthors(paper.authors),
        zotero_target_collection: TARGET_ZOTERO_COLLECTION,
        overflowCount: finalOverflowCount
    }
}));

const fs = require('fs');
const path = require('path');

// 1. Load the Zotero library items from the previous node
const zoteroItems = $items(); 

// 2. Build a Set of titles ONLY from parent items (avoiding "PDF" or "Snapshot" attachments)
const zoteroTitles = new Set();
zoteroItems.forEach(item => {
    const data = item.json.data;
    // We only care about main records, not attachments or notes
    if (data && ['journalArticle', 'preprint', 'book'].includes(data.itemType)) {
        if (data.title) {
            zoteroTitles.add(data.title.toLowerCase().trim());
        }
    }
});

// 3. Define path and read the local citation lookup file
const libraryPath = path.join('/data', 'citation_lookup_library.json');
// The citation library is optional; without it there is nothing to clean up.
if (!fs.existsSync(libraryPath)) return zoteroItems;
let lookupLibrary = {};
try { lookupLibrary = JSON.parse(fs.readFileSync(libraryPath, 'utf8') || '{}'); } catch (e) { return zoteroItems; }

// 4. Iterate and remove entries whose titles already exist in Zotero
let removedCount = 0;
for (const key in lookupLibrary) {
  const paperTitle = lookupLibrary[key].title?.toLowerCase().trim();

  if (zoteroTitles.has(paperTitle)) {
    delete lookupLibrary[key];
    removedCount++;
  }
}

// 5. Write the cleaned object back to disk
fs.writeFileSync(libraryPath, JSON.stringify(lookupLibrary, null, 2), 'utf8');

// Log the cleanup for your n8n history
console.log(`Cleanup complete: Removed ${removedCount} duplicates.`);

// 6. Return the original items unmodified
return zoteroItems;

// 1. Fetch data from nodes
const scirateItems = $('SciRate Fetch').all(); 
const arxivItems = $('arXiv Fetch').all();
const zoteroItems = $('Zotero Library').all();

// 2. Build Zotero ID Lookup
const existingIds = new Set();
zoteroItems.forEach(item => {
  const d = item.json?.data;
  if (!d) return;
  const matches = [d.archiveID, d.extra, d.url, d.DOI].join(" ").match(/[0-9]{4}\.[0-9]{4,5}/g);
  if (matches) matches.forEach(id => existingIds.add(id));
});

// 3. Helper to extract base ID
const getBaseId = (str) => {
  if (!str) return null;
  const match = str.match(/[0-9]{4}\.[0-9]{4,5}/);
  return match ? match[0] : null;
};

// 4. Merge using a Map
const masterMap = new Map();

// Load ArXiv papers
arxivItems.forEach(item => {
  const p = item.json;
  const id = getBaseId(p.url || p.id);
  if (id) {
    masterMap.set(id, { 
      ...p, 
      arxivId: id,
      source: 'arxiv',
      scites: 0,
      sortDate: p.published ? new Date(p.published).getTime() : 0
    });
  }
});

// Overlay SciRate papers
scirateItems.forEach(item => {
  const s = item.json;
  const id = getBaseId(s.arxivId || s.url || "");

  if (id) {
    const existing = masterMap.get(id);
    const sciteCount = parseInt(s.scites) || 0;

    if (existing) {
      // Keep ArXiv as primary, just add the scite count
      masterMap.set(id, {
        ...existing,
        scites: sciteCount
      });
    } else {
      // Paper only found on SciRate
      masterMap.set(id, {
        ...s,
        arxivId: id,
        source: 'scirate',
        scites: sciteCount,
        sortDate: s.published ? new Date(s.published).getTime() : 0,
        url: `https://arxiv.org/abs/${id}`
      });
    }
  }
});

// 5. SORTING LOGIC: ArXiv first (by date), then SciRate (by scites)
const finalResults = Array.from(masterMap.values())
  .filter(paper => !existingIds.has(paper.arxivId))
  .sort((a, b) => {
    // Priority 1: ArXiv source always comes before SciRate source
    if (a.source === 'arxiv' && b.source !== 'arxiv') return -1;
    if (a.source !== 'arxiv' && b.source === 'arxiv') return 1;

    // Priority 2: If both are ArXiv, sort by Date (Newest first)
    if (a.source === 'arxiv' && b.source === 'arxiv') {
      return b.sortDate - a.sortDate;
    }

    // Priority 3: If both are SciRate, sort by Scites (Highest first)
    if (a.source === 'scirate' && b.source === 'scirate') {
      return b.scites - a.scites;
    }

    return 0;
  });

// 6. Final Output
return finalResults.map(paper => ({
  json: {
    title: paper.title,
    authors: paper.authors,
    arxivId: paper.arxivId,
    scites: paper.scites,
    source: paper.source,
    url: paper.url || `https://arxiv.org/abs/${paper.arxivId}`,
    abstract: paper.abstract || "",
    published: paper.published
  }
}));

// Function to normalize author names into 'f_lastname' format
function normalizeName(name) {
  const parts = name.replace(/[^a-zA-Z\s]/g, '').trim().split(/\s+/);
  if (parts.length === 0 || !parts[0]) return '';
  if (parts.length === 1) return parts[0].toLowerCase();

  const lastName = parts[parts.length - 1].toLowerCase();
  const firstInitial = parts[0][0].toLowerCase();
  return `${firstInitial}_${lastName}`;
}

return $input.all().map(item => {
  const paper = item.json;

  // Parse raw author string into array of normalized names
  const rawAuthors = (paper.authors || '').split(',');
  const normalizedAuthors = rawAuthors
    .map(a => normalizeName(a.trim()))
    .filter(Boolean);

  return {
    json: {
      ...paper,
      normalized_authors: normalizedAuthors,
      // Concatenate title and abstract for embedding calculation
      embed_input: `Title: ${paper.title}\nAbstract: ${paper.abstract}`
    }
  };
});

return $input.all().map(item => {
  const paper = item.json;

  // ---------------------------------------------------------------------------
  // 1. Author Tier Evaluation
  // ---------------------------------------------------------------------------
  // Assumes your Merge node mapped the Postgres output to "author_db_matches"
  const authorMatches = paper.author_db_matches || [];
  let authorMultiplier = 1.0;
  let highestAuthorTier = 'None';

  authorMatches.forEach(match => {
    if (match.tier === 'Tier 1' && authorMultiplier < 1.30) {
      authorMultiplier = 1.30;
      highestAuthorTier = 'Tier 1';
    } else if (match.tier === 'Tier 2' && authorMultiplier < 1.15) {
      authorMultiplier = 1.15;
      highestAuthorTier = 'Tier 2';
    }
  });

  // ---------------------------------------------------------------------------
  // 2. Reference Paper Tiered Vector Multiplier
  // ---------------------------------------------------------------------------
  // Assumes your Merge node mapped the Vector Postgres output to "vector_matches"
  const topVectorMatches = paper.vector_matches || [];

  const refTierMultipliers = {
    'Tier 1': 1.30, 
    'Tier 2': 1.15, 
    'Tier 3': 1.00  
  };

  let maxWeightedSimilarity = 0.0;
  let topMatchedRef = { title: 'None', raw_similarity: 0.0, tier: 'None', weighted_similarity: 0.0 };

  topVectorMatches.forEach(match => {
    const rawSim = match.cosine_similarity || 0.0;
    const refTier = match.tier || 'Tier 3';
    const refMultiplier = refTierMultipliers[refTier] || 1.00;

    const weightedSim = rawSim * refMultiplier;

    // Pick the highest scoring match after tier multiplication
    if (weightedSim > maxWeightedSimilarity) {
      maxWeightedSimilarity = weightedSim;
      topMatchedRef = {
        title: match.matched_title,
        raw_similarity: Number(rawSim.toFixed(4)),
        tier: refTier,
        weighted_similarity: Number(weightedSim.toFixed(4))
      };
    }
  });

  // ---------------------------------------------------------------------------
  // 3. SciRate Boost Factor
  // ---------------------------------------------------------------------------
  const sciteBoost = 1.0 + (Math.log10((paper.scites || 0) + 1) * 0.1);

  // ---------------------------------------------------------------------------
  // 4. Calculate Final Composite Priority Score
  // ---------------------------------------------------------------------------
  // Composite = (Highest Weighted Vector Similarity) * (Author Multiplier) * (SciRate Boost)
  const compositeScore = Number((maxWeightedSimilarity * authorMultiplier * sciteBoost).toFixed(4));

  // ---------------------------------------------------------------------------
  // 5. Build Clean Output for the LLM
  // ---------------------------------------------------------------------------
  return {
    json: {
      arxivId: paper.arxivId,
      title: paper.title,
      authors: paper.authors,
      url: paper.url,
      abstract: paper.abstract,
      published: paper.published,
      // Explicit individual metrics for LLM decision-making
      scoring_breakdown: {
        composite_score: compositeScore,
        vector_similarity_raw: topMatchedRef.raw_similarity,
        vector_match_tier: topMatchedRef.tier,
        vector_similarity_weighted: topMatchedRef.weighted_similarity,
        matched_reference_title: topMatchedRef.title,
        author_tier: highestAuthorTier,
        author_multiplier: authorMultiplier,
        raw_scites: paper.scites || 0,                 
        scite_boost: Number(sciteBoost.toFixed(3))     
      }
    }
  };
});

const translator = String($env.ZOTERO_TRANSLATOR_URL || 'http://zotero-translator:1969').match(/^https?:\/\/([^:\/]+)(?::(\d+))?/) || [];
const http = require('http');

// 1. Build a resilient fallback cascade to get a clean identifier Zotero loves
// Checks for native Postgres snake_case, camelCase, or Semantic Scholar API nested IDs
const identifier = $json.doi 
  || $json.arxiv_id 
  || $json.arxivId 
  || ($json.externalIds ? $json.externalIds.ArXiv : null);

// 2. Guard Clause: If no valid ID exists, or it's a Semantic Scholar URL, exit gracefully
if (!identifier || String(identifier).includes('semanticscholar.org')) {
  return { 
    json: { 
      success: false, 
      reason: "Skipped: No clean DOI or arXiv ID available for Zotero translation." 
    } 
  };
}

const fetchMetadata = (id) => {
  return new Promise((resolve, reject) => {
    const payload = String(id).trim();

    const options = {
      hostname: translator[1],
      port: Number(translator[2] || 80),
      path: '/search',
      method: 'POST',
      headers: {
        'Content-Type': 'text/plain',
        'Content-Length': Buffer.byteLength(payload)
      }
    };

    const req = http.request(options, (res) => {
      let rawData = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => { rawData += chunk; });

      res.on('end', () => {
        try {
          if (res.statusCode !== 200) {
            return reject(new Error(`Zotero translation server returned status ${res.statusCode}`));
          }
          const parsedData = JSON.parse(rawData);
          resolve(parsedData[0] || parsedData);
        } catch (e) {
          reject(e);
        }
      });
    });

    req.on('error', (e) => reject(e));
    req.write(payload);
    req.end();
  });
};

try {
  const result = await fetchMetadata(identifier);

  if (result && typeof result === 'object') {
    result.collections = [$env.ZOTERO_COLLECTION_KEY];
  }

  return { json: { success: true, data: result } };
} catch (error) {
  // Return the error as data instead of crashing the whole workflow execution thread
  return { 
    json: { 
      success: false, 
      error: error.message,
      attemptedIdentifier: identifier
    } 
  };
}

const MIN_COMPOSITE_THRESHOLD = Number($env.SCOUT_MIN_SCORE || 0.75);
const MAX_PAPERS_CEILING = Number($env.SCOUT_MAX_CANDIDATES || 100);

// Helper function to safely extract the score across different naming conventions
function getScore(paper) {
    if (paper.scoring_breakdown && paper.scoring_breakdown.composite_score !== undefined) {
        return paper.scoring_breakdown.composite_score;
    }
    return paper.compositeScore ?? paper.composite_score ?? paper.score ?? 0;
}

// 1. Filter using the score
const validPapers = $input.all()
    .map(item => item.json)
    .filter(paper => getScore(paper) >= MIN_COMPOSITE_THRESHOLD);

// 2. Sort descending by composite score
validPapers.sort((a, b) => getScore(b) - getScore(a));

// 3. Enforce max ceiling cap and format output for n8n
return validPapers.slice(0, MAX_PAPERS_CEILING).map(paper => ({ json: paper }));

// Categories come from ARXIV_CATEGORIES (comma separated), e.g. quant-ph,cs.LG
return String($env.ARXIV_CATEGORIES || 'quant-ph')
  .split(',')
  .map(c => c.trim())
  .filter(Boolean)
  .map(cat => ({ json: { cat } }));
